// ---- src/bbm-appbar.js
const { buildAppBar } = (() => {
// One sticky bar: the site's nav, league picker, refresh buttons, search,
// theme button and season pill. Existing nodes are moved, never cloned, so the
// page's postbacks and dropdown scripts keep working.
function buildAppBar() {
  const nav = document.querySelector("nav.navbar");
  const row = document.querySelector(".page-title-row");
  if (!nav || !row || nav.closest(".cgm-appbar")) return;

  const bar = Object.assign(document.createElement("header"), { className: "cgm-appbar" });
  nav.before(bar);
  bar.append(nav, row);

  // The page name moves out of the bar so the controls fit at 1440 px.
  const head = row.querySelector(".page-header");
  const title = head?.querySelector("h1")?.textContent.trim();
  if (head && title && title !== "Basketball Monster") {
    head.classList.add("cgm-pagehead");
    (document.querySelector(".favorites-toolbar") || bar).after(head);
  } else {
    head?.remove();
  }

  const publish = () => document.documentElement.style.setProperty("--cgm-bar-h", `${bar.offsetHeight}px`);
  publish();
  addEventListener("resize", publish);
}
return { buildAppBar };
})();

// ---- src/scoring.js
const { CATEGORIES, DEFAULT_WEIGHTS, puntSummary, sanitizeWeights, selectDraftablePool, scorePlayers, weightedScore, fitWeights, NEUTRAL, POSITIVE, NEGATIVE, heatColor } = (() => {
const CATEGORIES = [
  { key: "pts", label: "PTS" },
  { key: "reb", label: "REB" },
  { key: "ast", label: "AST" },
  { key: "stl", label: "STL" },
  { key: "blk", label: "BLK" },
  { key: "threes", label: "3PM" },
  { key: "fg", label: "FG%" },
  { key: "ft", label: "FT%" },
  { key: "turnovers", label: "TO" }
];

const DEFAULT_WEIGHTS = Object.freeze(
  Object.fromEntries(CATEGORIES.map(({ key }) => [key, 1]))
);

// "None", or each punted category: "AST" (weight 0) or "BLK ×0.5" (partial).
function puntSummary(weights) {
  const parts = CATEGORIES.filter(({ key }) => weights[key] < 1)
    .map(({ key, label }) => (weights[key] === 0 ? label : `${label} ×${weights[key]}`));
  return parts.length ? parts.join(", ") : "None";
}

function sanitizeWeights(weights = {}) {
  return Object.fromEntries(
    CATEGORIES.map(({ key }) => {
      const value = Number(weights[key]);
      return [key, Number.isFinite(value) ? Math.min(2, Math.max(0, value)) : 1];
    })
  );
}

function selectDraftablePool(players, size) {
  if (!Array.isArray(players) || players.length <= size) return players || [];
  const kept = new Set(scorePlayers(players).slice(0, size).map((player) => player.id));
  return players.filter((player) => kept.has(player.id));
}

function scorePlayers(players, requestedWeights = DEFAULT_WEIGHTS, pool = players) {
  if (!Array.isArray(players) || players.length === 0) return [];
  const weights = sanitizeWeights(requestedWeights);
  const baseline = pool.length > 0 ? pool : players;
  const poolFgPct = shootingBaseline(baseline, "fieldGoals", "fieldGoalAttempts");
  const poolFtPct = shootingBaseline(baseline, "freeThrows", "freeThrowAttempts");
  const valuesOf = (player) => ({
    pts: player.pts,
    reb: player.reb,
    ast: player.ast,
    stl: player.stl,
    blk: player.blk,
    threes: player.threes,
    fg: (player.fgPct - poolFgPct) * player.fgaPerGame,
    ft: (player.ftPct - poolFtPct) * player.ftaPerGame,
    turnovers: player.turnovers
  });

  const baselineValues = baseline.map(valuesOf);
  const distributions = Object.fromEntries(
    CATEGORIES.map(({ key }) => {
      const values = baselineValues.map((value) => value[key]);
      const mean = values.reduce((sum, value) => sum + value, 0) / values.length;
      const variance = values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / values.length;
      return [key, { mean, deviation: Math.sqrt(variance) }];
    })
  );
  const withValues = players.map((player) => ({ ...player, values: valuesOf(player) }));

  const scored = withValues.map((player) => {
    const z = Object.fromEntries(
      CATEGORIES.map(({ key }) => {
        const { mean, deviation } = distributions[key];
        const direction = key === "turnovers" ? -1 : 1;
        const value = deviation === 0 ? 0 : direction * (player.values[key] - mean) / deviation;
        return [key, value];
      })
    );
    return { ...player, z, score: weightedScore(z, weights) };
  });

  return scored
    .sort((left, right) => right.score - left.score || left.name.localeCompare(right.name))
    .map((player, index) => ({ ...player, rank: index + 1 }));
}

function weightedScore(z, weights) {
  const total = CATEGORIES.reduce((sum, { key }) => sum + weights[key], 0);
  if (total === 0) return 0;
  return CATEGORIES.reduce((sum, { key }) => sum + z[key] * weights[key], 0) / total;
}

// Fit raises each active category's weight by the per-pick gap between the
// average team and the manager's roster, capped at double weight.
function fitWeights(weights, gapPerPick) {
  return Object.fromEntries(
    CATEGORIES.map(({ key }) => [key, weights[key] * (1 + Math.min(1, Math.max(0, gapPerPick[key] || 0)))])
  );
}

function shootingBaseline(players, made, attempts) {
  const totalAttempts = players.reduce((sum, player) => sum + player[attempts], 0);
  return totalAttempts > 0 ? players.reduce((sum, player) => sum + player[made], 0) / totalAttempts : 0;
}

// Breakout-style heatmap: a dark neutral cell that ramps toward teal for
// positive values and red for negative values, full strength at |z| = 2.5.
const NEUTRAL = [30, 36, 50];
const POSITIVE = [0, 168, 142];
const NEGATIVE = [228, 34, 66];

function heatColor(zScore) {
  const strength = Math.min(1, Math.abs(zScore) / 2) ** 0.8;
  const target = zScore >= 0 ? POSITIVE : NEGATIVE;
  const channel = (index) => Math.round(NEUTRAL[index] + (target[index] - NEUTRAL[index]) * strength);
  return `rgb(${channel(0)}, ${channel(1)}, ${channel(2)})`;
}
return { CATEGORIES, DEFAULT_WEIGHTS, puntSummary, sanitizeWeights, selectDraftablePool, scorePlayers, weightedScore, fitWeights, NEUTRAL, POSITIVE, NEGATIVE, heatColor };
})();

// ---- src/bbm-heat.js
const { parseColor, classifyHeat, contrast, cellHeat, ensureContrast, toCss, ensureTextContrast } = (() => {
// Re-colours Basketball Monster's pastel heat cells onto ClutchGM's scale:
// teal for above average, red for below, white-and-bold numbers on the strong
// end. Pure functions; the DOM work lives in bbm-board.js.


const DARK_TEXT = [0, 0, 0];
const WHITE = [255, 255, 255];

function parseColor(text) {
  const match = String(text || "").trim().match(/^(?:rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)|#([0-9a-f]{3}|[0-9a-f]{6})\b)/i);
  if (!match) return null;
  if (match[1] !== undefined) return [match[1], match[2], match[3]].map(Number);
  const hex = match[4].length === 3 ? [...match[4]].map((c) => c + c).join("") : match[4];
  return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
}

// Classifies a BBM heat background. Greens are good, reds/pinks are bad,
// cyan is informational (Adv%), anything else (gold ownership cells, tier and
// status colours) is not a heat cell and must be left alone.
function classifyHeat(rgb) {
  if (!rgb) return null;
  const [r, g, b] = rgb;
  const low = Math.min(r, g, b);
  const strength = Math.min(1, (255 - low) / 255 / 0.7);
  if (strength < 0.02) return { kind: "neutral", z: 0 };
  if (g - r > 12 && g - b > 12) return { kind: "up", z: strength * 2 };
  if (r - g > 12 && Math.abs(g - b) < 40) return { kind: "down", z: -strength * 2 };
  if (r >= 140 && b - r > 30 && g - r > 30) return { kind: "info", z: 0 };
  return null;
}

const mix = (from, to, amount) => from.map((value, index) => Math.round(value + (to[index] - value) * amount));
const channel = (value) => { const c = value / 255; return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
const luminance = ([r, g, b]) => 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
const contrast = (a, b) => { const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x); return (hi + 0.05) / (lo + 0.05); };
const css = ([r, g, b]) => `rgb(${r}, ${g}, ${b})`;

// Light pages ramp from white; dark pages use the side panel's own ramp.
// The text colour is whichever of near-black and white reads better.
function cellHeat(z, theme) {
  const strength = Math.min(1, Math.abs(z) / 2) ** 0.8;
  const target = z >= 0 ? POSITIVE : NEGATIVE;
  const background = theme === "dark"
    ? heatColor(z).match(/\d+/g).map(Number)
    : mix(WHITE, target, strength * 0.9);
  const text = contrast(background, WHITE) >= contrast(background, DARK_TEXT) ? WHITE : DARK_TEXT;
  return { background: css(background), color: css(text), neutral: theme === "dark" ? NEUTRAL : WHITE };
}

// Chips the site colours itself (status squares, analyst tags) are often white
// on a mid-tone. Nudge the background toward black or white until the text
// reaches the target contrast, keeping the hue.
function ensureContrast(background, text, target = 4.5) {
  let result = background;
  const toward = luminance(text) > luminance(background) ? [0, 0, 0] : [255, 255, 255];
  for (let step = 0; step < 25 && contrast(result, text) < target; step++) result = mix(result, toward, 0.06);
  return result;
}

const toCss = css;

// Last resort for text the site coloured for the other theme: keep the hue,
// move it toward black or white until it reaches the target contrast.
function ensureTextContrast(text, background, target = 4.5) {
  if (contrast(text, background) >= target) return text;
  const toward = contrast([0, 0, 0], background) >= contrast([255, 255, 255], background) ? [0, 0, 0] : [255, 255, 255];
  let result = text;
  for (let step = 0; step < 25 && contrast(result, background) < target; step++) result = mix(result, toward, 0.08);
  if (contrast(result, background) < target) return toward;
  return result;
}
return { parseColor, classifyHeat, contrast, cellHeat, ensureContrast, toCss, ensureTextContrast };
})();

// ---- src/bbm-theme.js
const { currentTheme, onThemeChange } = (() => {
// The site ships a light and a dark stylesheet driven by CSS variables, so the
// redesign borrows those variables and only needs to know which one is live
// for the few things a variable cannot express (heat-cell ramps).


function currentTheme() {
  const token = getComputedStyle(document.documentElement).getPropertyValue("--color-bg-primary").trim();
  const rgb = parseColor(token) || parseColor(getComputedStyle(document.body).backgroundColor);
  if (!rgb) return "light";
  return (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255 < 0.45 ? "dark" : "light";
}

// The theme button submits the page, but a script could also swap the
// stylesheet live; follow either.
function onThemeChange(callback) {
  let last = currentTheme();
  const check = () => { const next = currentTheme(); if (next !== last) { last = next; callback(next); } };
  new MutationObserver(check).observe(document.head, { childList: true, attributes: true, subtree: true });
  new MutationObserver(check).observe(document.documentElement, { attributes: true });
}
return { currentTheme, onThemeChange };
})();

// ---- src/bbm-board.js
const { applyHeat, fixChips, buildBoards, paintBoards } = (() => {
// Turns Basketball Monster's data tables into boards: one scroller, sticky
// header and name column, repeated round headers folded into dividers, and
// heat cells on ClutchGM's scale.



const TABLES = "table.modern-stats-table, table.rankings-table, table.datatable";
const TALL_ROWS = 8;

const cellsOf = (row) => [...row.children].filter((cell) => cell.matches("th, td"));
const isHeaderRow = (row) => row.children.length > 0 && cellsOf(row).every((cell) => cell.tagName === "TH");

function wrap(table) {
  const host = table.parentElement;
  const board = host.classList.contains("modern-table-container") && host.children.length === 1
    ? host
    : Object.assign(document.createElement("div"), { className: "" });
  if (board !== host) { table.before(board); board.append(table); }
  board.classList.add("cgm-board");
  if (table.rows.length >= TALL_ROWS) board.classList.add("cgm-board--tall");
  return board;
}

// BBM repeats the header row every round. Keep the first, turn the rest into
// "Round N" dividers when there is a Round column, otherwise hide them.
function foldRepeatedHeaders(table) {
  const rows = [...table.rows];
  const first = rows.find(isHeaderRow);
  if (!first) return;
  const labels = cellsOf(first).map((cell) => cell.textContent.trim().toLowerCase());
  const roundAt = labels.findIndex((label) => label === "round" || label === "rd");
  for (const row of rows) {
    if (row === first || !isHeaderRow(row) || row.closest("thead")) continue;
    const next = row.nextElementSibling;
    const round = roundAt >= 0 && next ? cellsOf(next)[roundAt]?.textContent.trim() : "";
    if (round) {
      const cell = Object.assign(document.createElement("td"), { colSpan: row.children.length, textContent: `Round ${round}` });
      row.replaceChildren(cell);
      row.className = "cgm-round-row";
    } else {
      row.classList.add("cgm-dup-head");
    }
  }
}

function stickName(table) {
  const header = [...table.rows].find(isHeaderRow);
  if (!header) return;
  const index = cellsOf(header).findIndex((cell) => /^(name|player)$/i.test(cell.textContent.trim()));
  if (index < 0) return;
  for (const row of table.rows) {
    const cells = cellsOf(row);
    if (cells.length === header.children.length) cells[index].classList.add("cgm-sticky-col");
  }
}

function applyHeat(root = document) {
  const theme = currentTheme();
  for (const cell of root.querySelectorAll('td.text-force-black[style*="background-color"]')) {
    if (!cell.closest(".cgm-board") || cell.querySelector(".status-square")) continue; // status cells are not heat
    const original = cell.dataset.cgmBg ?? (cell.dataset.cgmBg = cell.style.backgroundColor);
    const heat = classifyHeat(parseColor(original));
    cell.classList.remove("cgm-heat", "cgm-heat-info", "cgm-heat-neutral");
    if (!heat) { cell.style.backgroundColor = original; cell.style.removeProperty("color"); continue; }
    if (heat.kind === "up" || heat.kind === "down") {
      const { background, color } = cellHeat(heat.z, theme);
      cell.style.backgroundColor = background;
      cell.style.setProperty("color", color, "important");
      cell.classList.add("cgm-heat");
    } else {
      cell.style.backgroundColor = "";
      cell.style.removeProperty("color");
      cell.classList.add(heat.kind === "info" ? "cgm-heat-info" : "cgm-heat-neutral");
    }
  }
}

// Status cells, status squares and analyst tags carry their own inline colours,
// often white text on a mid-tone. Nudge each background until its text reads.
const textNode = (el) => [...el.childNodes].some((node) => node.nodeType === 3 && node.textContent.trim());
const textColorOf = (el) => {
  const source = textNode(el) ? el : [...el.querySelectorAll("*")].find(textNode) || el;
  return parseColor(getComputedStyle(source).color);
};

function fixChips() {
  const targets = ".badge, .tier-badge, .progress-bar, .cgm-board [style*='background-color'], .daily-status-updates [style*='background-color'], [style*='background-color']";
  for (const chip of document.querySelectorAll(targets)) {
    if (chip.classList.contains("cgm-heat") || chip.closest(".cgm-appbar .bm-custom-select, .cgm-appbar .player-search")) continue;
    // Work from the colours first seen, so repeated passes agree with each other.
    if (!chip.dataset.cgmBg0) {
      const css = getComputedStyle(chip).backgroundColor;
      if (/^transparent$|^rgba\(.*,\s*0\)$/.test(css)) continue;
      const background = parseColor(css);
      const text = textColorOf(chip);
      if (!background || !text) continue;
      // Pale fills are rows and highlights; their text is repaired by bbm-legibility.js instead.
      if (contrast(background, [255, 255, 255]) < 2.2) continue;
      chip.dataset.cgmBg0 = background.join(",");
      chip.dataset.cgmFg0 = text.join(",");
    }
    const background = chip.dataset.cgmBg0.split(",").map(Number);
    const text = chip.dataset.cgmFg0.split(",").map(Number);
    const fixed = ensureContrast(background, text);
    if (fixed.some((value, index) => value !== background[index])) {
      chip.style.setProperty("background-color", toCss(fixed), "important");
      chip.dataset.cgmChip = "1";
    }
  }
}

function buildBoards() {
  for (const table of document.querySelectorAll(TABLES)) {
    if (table.closest(".cgm-board, .cgm-home")) continue;
    wrap(table);
    foldRepeatedHeaders(table);
    stickName(table);
  }
}

// Colour work reads the live theme, so it waits for the site's stylesheets.
function paintBoards() {
  applyHeat();
  fixChips();
}
return { applyHeat, fixChips, buildBoards, paintBoards };
})();

// ---- src/bbm-disclose.js
const { accordion, limit, segmented, foldNotices, clamp } = (() => {
// Progressive disclosure for BBM pages: sections that fold, and long lists that
// show a few rows with a "Show all" toggle. Nodes are moved, never cloned, so
// ASP.NET postbacks and the site's own handlers keep working.
const KEY = "cgmBbmOpen";
const read = () => { try { return JSON.parse(localStorage.getItem(KEY)) || {}; } catch { return {}; } };
const remember = (id, open) => { try { localStorage.setItem(KEY, JSON.stringify({ ...read(), [id]: open })); } catch { /* storage blocked */ } };

const make = (tag, className, text) => Object.assign(document.createElement(tag), { className, ...(text === undefined ? {} : { textContent: text }) });

// Turn a titled card into <details>. The heading becomes the summary; the rest
// of the card is the body. The last open/closed choice is remembered per id.
function accordion(card, id, { open = false, count } = {}) {
  const heading = card?.querySelector("h3");
  if (!heading || card.closest("details.cgm-acc")) return null;
  const href = heading.querySelector("a")?.getAttribute("href");
  const wrapper = heading.parentElement;

  const summary = document.createElement("summary");
  summary.append(heading);
  if (count != null) summary.append(make("span", "cgm-count", count));
  if (href) summary.append(Object.assign(make("a", "cgm-acc-open", "Open"), { href }));
  if (wrapper !== card && !wrapper.children.length) wrapper.remove();

  const body = make("div", "cgm-acc-body");
  body.append(...card.childNodes);
  const details = make("details", "cgm-acc");
  details.open = read()[id] ?? open;
  details.append(summary, body);
  card.append(details);
  details.addEventListener("toggle", () => remember(id, details.open));
  return { details, body };
}

// Show the first `count` items and fold the rest behind a toggle.
function limit(items, count, host, noun = "", total = items.length) {
  if (items.length <= count) return;
  host.classList.add("cgm-limited");
  items.slice(count).forEach((item) => item.classList.add("cgm-more"));
  const more = `Show all ${total}${noun ? ` ${noun}` : ""}`;
  const button = Object.assign(make("button", "cgm-show-all", more), { type: "button" });
  button.addEventListener("click", () => {
    button.textContent = host.classList.toggle("cgm-expanded") ? "Show fewer" : more;
  });
  if (host.matches("table")) host.after(button);
  else host.append(button);
}

// A one-choice-at-a-time segmented control. options: [{ key, label }].
function segmented(options, onPick, initial = options[0].key) {
  const bar = make("div", "cgm-seg");
  const buttons = options.map(({ key, label }) => {
    const button = Object.assign(make("button", "cgm-seg-btn", label), { type: "button" });
    button.setAttribute("aria-pressed", String(key === initial));
    button.addEventListener("click", () => {
      buttons.forEach((other) => other.setAttribute("aria-pressed", String(other === button)));
      onPick(key);
    });
    return button;
  });
  bar.append(...buttons);
  return bar;
}

// Informational banners (tips, "we have a new tool") come first on several
// pages and push the real content down. Gather them into one folded row.
const NOTICE = ".system-message--info, .alert-primary, .alert-secondary, .alert-info";
function foldNotices() {
  const notices = [...document.querySelectorAll(NOTICE)].filter((el) => !el.closest("details, table, .cgm-controlbar, .cgm-drawer"));
  if (!notices.length || document.querySelector(".cgm-notes")) return;
  const details = make("details", "cgm-notes");
  const summary = make("summary", "", `Notes (${notices.length})`);
  notices[0].before(details);
  details.append(summary, ...notices);
}

// Long prose paragraphs show two lines until asked.
function clamp(el, id) {
  if (!el || el.dataset.cgmClamped) return;
  el.dataset.cgmClamped = "1";
  el.classList.add("cgm-clamp");
  const button = Object.assign(make("button", "cgm-show-all", "Read more"), { type: "button" });
  button.addEventListener("click", () => { button.textContent = el.classList.toggle("cgm-clamp") ? "Read more" : "Read less"; });
  el.after(button);
}
return { accordion, limit, segmented, foldNotices, clamp };
})();

// ---- src/bbm-depth.js
const { buildDepth } = (() => {
// Depth Charts floats 30 fixed-width team tables, each with its full bench, down
// one very long page. Lay the teams out as a grid of cards that show the
// starters and fold the bench behind a toggle.


const STARTERS = 5;

function buildDepth() {
  const cards = [...document.querySelectorAll(".container-fluid.float-left")].filter((card) => card.querySelector(":scope > h2 + table"));
  if (!cards.length || document.querySelector(".cgm-teamgrid")) return;

  const grid = Object.assign(document.createElement("div"), { className: "cgm-teamgrid" });
  cards[0].before(grid);
  for (const card of cards) {
    card.classList.add("cgm-teamcard");
    card.removeAttribute("style");
    grid.append(card);
    const table = card.querySelector("table");
    const rows = [...table.querySelectorAll("tr")].filter((row) => !row.closest("thead"));
    const players = rows.filter((row) => row.querySelector("a")).length;
    limit(rows, STARTERS, table, "players", players);
  }
}
return { buildDepth };
})();

// ---- src/bbm-filters.js
const { buildControlBar } = (() => {
// Collapses the big filter panel into a control bar: current selections as
// chips, the position filter and refresh/export buttons always at hand, and
// the original panel (moved, not cloned) as a drawer behind a Filters button.
const NEUTRAL_VALUES = /^(none|no filter|all|all teams|all players|home\/away|all tags)$/i;

const make = (tag, className, text) => {
  const node = Object.assign(document.createElement(tag), { className });
  if (text) node.textContent = text;
  return node;
};

function chipsFor(container) {
  const chips = [];
  for (const select of container.querySelectorAll("select[id], select[name]")) {
    if (select.closest("#PositionsFilterControl")) continue;
    const selected = select.selectedOptions[0]?.textContent.trim();
    if (!selected || NEUTRAL_VALUES.test(selected)) continue;
    const label = select.closest(".modern-filter-group")?.querySelector(":scope > .modern-filter-label, .modern-filter-label")?.textContent.trim();
    const chip = make("button", "cgm-chip");
    chip.type = "button";
    chip.append(...(label ? [make("span", "cgm-chip-label", label), make("span", "cgm-chip-value", selected)] : [make("span", "cgm-chip-value", selected)]));
    chips.push(chip);
  }
  return chips;
}

// Sections made of these controls are filters and belong in the drawer. Any
// other section (a trade picker, a team list, notes) is page content and stays visible.
const FILTER_IDS = /DataSetControl|DateFilterControl|ProjectionSourceControl|ValueDisplayType|StatDisplayType|EditDisplayColumns|PlayerFilterControl|TeamFilterControl|PositionsFilterControl|RefreshButton|PuntCategoriesControl|HomeAwayFilterControl/;
const isFilterSection = (section) => [...section.querySelectorAll("[id], [name]")].some((node) => FILTER_IDS.test(node.id || node.getAttribute("name")));

// A section holding a table, a multi-select or a textarea is page content, not a setting.
// Draft-day actions (search a player, mark drafted or targeted) stay in view too,
// and so do the trade page's own actions, which submit buttons carry as a name
// rather than an id.
const ACTION_IDS = /DraftOtherButton|DraftMeButton|QueuePlayerButton|NameTextBox/;
const ACTION_NAMES = /AnalyzeChangesButton|FINDTRADES|FINDFREEAGENTS/;
const isContentSection = (section) => !!section.querySelector("table, select[multiple], textarea")
  || !![...section.querySelectorAll("[id]")].some((node) => ACTION_IDS.test(node.id))
  || !![...section.querySelectorAll("input[type='submit'][name]")].some((node) => ACTION_NAMES.test(node.name));
const summaryOf = (section) => (section.querySelector("b, h2, h3, h4, .modern-filter-section-title, div[style*='font-size']")?.textContent || "More").replace(/\s+/g, " ").trim().slice(0, 60);

const groupOf = (node) => node?.closest(".modern-filter-group") || node;

// Trade Monster's Current Analysis and Reset sit in the panel's own action row,
// directly above the four Analyze buttons, and Reset clears every action the
// reader has set. They are page actions, not settings, so they leave the drawer
// with the buttons they belong to; the row's Refresh button and Show Monster Bar
// checkbox stay behind with the other settings.
const PANEL_ACTION_NAMES = /^(RESET|MasterRefreshButton)$/;

// The card's own sentences ("Analyze Trade - Select a Team 2 ... then click")
// become each button's hover text, so the card is a row of buttons about one
// row tall instead of four paragraphs.
const holdsControl = (node) => !!node?.querySelector("input, select, button, textarea, label, table, img");
const dropIfEmptied = (node) => { if (node && !holdsControl(node) && !node.textContent.trim()) node.remove(); };

function compactActionCard(container, card) {
  if (!card) return;
  const row = make("div", "cgm-trade-run");
  for (const button of container.querySelectorAll("input[type='submit'][name]")) {
    if (!PANEL_ACTION_NAMES.test(button.name)) continue;
    const group = button.closest(".modern-filter-group");
    row.append(button);
    dropIfEmptied(group);
  }
  for (const button of [...card.querySelectorAll("input[type='submit'][name]")]) {
    if (!ACTION_NAMES.test(button.name)) continue;
    const help = button.closest(".p-1");
    if (help) button.title = help.textContent.replace(/\s+/g, " ").trim();
    row.append(button);
    help?.remove();
  }
  if (!row.children.length) return;
  card.prepend(row);
  for (const child of [...card.children]) dropIfEmptied(child);
}

function buildControlBar() {
  const container = document.querySelector(".modern-filter-container");
  if (!container || document.querySelector(".cgm-zone")) return;

  const zone = make("div", "cgm-zone");
  const bar = make("div", "cgm-controlbar");
  container.before(zone);
  // Only the bar goes in the zone. The zone is sticky, so a tall panel inside it
  // would stay pinned over the page and cover the card's buttons as soon as the
  // reader scrolled; as a flow sibling the panel scrolls away normally.
  zone.append(bar);
  container.classList.add("cgm-drawer");

  // Small content tables that sit above the page's main table fold away, so
  // the main table starts near the top.
  const rowsIn = (section) => Math.max(0, ...[...section.querySelectorAll("table")].map((table) => table.rows.length));
  const mainRowsAfter = (section) => Math.max(0, ...[...document.querySelectorAll("table")]
    .filter((table) => !section.contains(table) && section.compareDocumentPosition(table) & Node.DOCUMENT_POSITION_FOLLOWING)
    .map((table) => table.rows.length));
  // The section carrying the page's own action submits is where the panel's
  // action row moves to, so Reset and Current Analysis sit beside the actions.
  const actionsCard = [...container.querySelectorAll(":scope > .modern-filter-section")]
    .find((section) => [...section.querySelectorAll("input[type='submit'][name]")].some((node) => ACTION_NAMES.test(node.name)));

  let anchor = zone;
  for (const section of [...container.querySelectorAll(":scope > .modern-filter-section")]) {
    if (isFilterSection(section) || !isContentSection(section)) continue;
    let moved = section;
    if (rowsIn(section) > 0 && rowsIn(section) * 3 < mainRowsAfter(section)) {
      const fold = Object.assign(document.createElement("details"), { className: "cgm-fold" });
      fold.append(Object.assign(document.createElement("summary"), { textContent: summaryOf(section) }), section);
      moved = fold;
    }
    anchor.after(moved);
    anchor = moved;
  }
  compactActionCard(container, actionsCard);

  const title = document.querySelector(".cgm-pagehead");
  if (title) bar.append(title);

  const toggle = make("button", "cgm-filters-toggle", "Filters");
  toggle.type = "button";
  toggle.setAttribute("aria-expanded", "false");
  bar.append(toggle);

  const chipRow = make("div", "cgm-chips");
  bar.append(chipRow);
  const positions = container.querySelector("#PositionsFilterControl");
  if (positions) {
    const slot = make("div", "cgm-slot cgm-positions");
    slot.append(groupOf(positions));
    bar.append(slot);
  }
  const actions = make("div", "cgm-slot cgm-actions");
  for (const id of ["RefreshButton", "EXCELBUTTON", "CSVBUTTON"]) {
    const button = container.querySelector(`#${id}`);
    if (button) actions.append(groupOf(button));
  }
  bar.append(actions);

  const refreshChips = () => chipRow.replaceChildren(...chipsFor(container));
  refreshChips();

  const setOpen = (open) => {
    zone.classList.toggle("cgm-open", open);
    toggle.setAttribute("aria-expanded", String(open));
  };
  toggle.addEventListener("click", () => setOpen(!zone.classList.contains("cgm-open")));
  // Only a chip opens the drawer: a click on the bar's empty space must not
  // drop the panel over the page the reader was aiming at.
  chipRow.addEventListener("click", (event) => { if (event.target.closest(".cgm-chip")) setOpen(true); });
  document.addEventListener("keydown", (event) => { if (event.key === "Escape") setOpen(false); });
  document.addEventListener("click", (event) => { if (!zone.contains(event.target) && !container.contains(event.target)) setOpen(false); });

  for (const section of container.querySelectorAll(".modern-filter-section")) {
    if (!section.querySelector("*:not(.modern-filter-row):not(.modern-filter-group)")) section.remove();
  }

  const publish = () => document.documentElement.style.setProperty("--cgm-zone-h", `${bar.offsetHeight}px`);
  publish();
  addEventListener("resize", publish);
}
return { buildControlBar };
})();

// ---- src/bbm-home.js
const { buildNews, buildGames, buildHome } = (() => {
// The home page lays its widgets out as a row of equal cards that all show
// everything at once. Regroup the same nodes into three columns and fold what
// is secondary: sections are accordions, lists show a few rows, and each game
// opens on demand.


const slotOf = (col) => {
  if (col.querySelector(".daily-status-updates")) return "games";
  const title = col.querySelector("h3")?.textContent.trim().toLowerCase() || "";
  if (title.includes("player news")) return "news";
  if (title.includes("draft kit")) return "articles";
  if (title.includes("user comments")) return "comments";
  if (title.includes("roster changes")) return "roster";
  if (title.includes("analysts")) return "analysts";
  return null;
};

const INJURY = /injur|quest|doubt|\bout\b|prob|gtd|day/i;
const NEWS_VISIBLE = 10;

function buildNews(body) {
  const cards = [...body.querySelectorAll(".news-card")];
  for (const card of cards) {
    const label = card.querySelector(".news-card-test-status-corner")?.textContent.trim() || "";
    card.dataset.cgmKind = INJURY.test(label) ? "injury" : "update";
    card.addEventListener("click", (event) => {
      if (!event.target.closest("a, button, input, label, select")) card.classList.toggle("cgm-open");
    });
  }

  const state = { kind: "all", all: false };
  const counts = { all: cards.length, injury: cards.filter((c) => c.dataset.cgmKind === "injury").length };
  counts.update = counts.all - counts.injury;
  const apply = () => {
    let shown = 0;
    for (const card of cards) {
      const match = state.kind === "all" || card.dataset.cgmKind === state.kind;
      card.classList.toggle("cgm-gone", !match || (!state.all && ++shown > NEWS_VISIBLE));
    }
    const total = state.kind === "all" ? counts.all : counts[state.kind];
    more.hidden = total <= NEWS_VISIBLE;
    more.textContent = state.all ? "Show fewer" : `Show all ${total}`;
  };

  const more = Object.assign(document.createElement("button"), { type: "button", className: "cgm-show-all" });
  more.addEventListener("click", () => { state.all = !state.all; apply(); });

  const bar = document.createElement("div");
  bar.className = "cgm-newsbar";
  bar.append(segmented(
    [{ key: "all", label: `All ${counts.all}` }, { key: "injury", label: `Injuries ${counts.injury}` }, { key: "update", label: `Updates ${counts.update}` }],
    (key) => { state.kind = key; state.all = false; apply(); }
  ));
  const mine = [body.querySelector("#MYONLY"), body.querySelector('label[for="MYONLY"]')].filter(Boolean);
  const mineBox = document.createElement("span");
  mineBox.className = "cgm-mine";
  mineBox.append(...mine);
  bar.append(mineBox);

  body.prepend(bar);
  body.append(more);
  apply();
}

// The games widget is a flat run of divs: time, matchup, then player rows.
function buildGames(box) {
  const groups = [];
  const notes = [];
  for (const el of [...box.children]) {
    if (el.matches('[class*="daily-status-updates-game"]')) groups.push({ time: el, teams: null, players: [] });
    else if (!groups.length) continue;
    else if (el.classList.contains("daily-status-updates-teams")) groups.at(-1).teams = el;
    else if (el.querySelector("a")) groups.at(-1).players.push(el);
    else notes.push(el); // the "no player status" legend
  }
  for (const { time, teams, players } of groups) {
    const details = document.createElement("details");
    details.className = "cgm-game";
    const summary = document.createElement("summary");
    summary.append(...[teams, time].filter(Boolean));
    if (players.length) summary.append(Object.assign(document.createElement("span"), { className: "cgm-count", textContent: String(players.length) }));
    details.append(summary, ...players);
    box.append(details);
  }
  notes.forEach((note) => box.append(note));
}

function buildHome() {
  const row = document.querySelector(".container-fluid > .row");
  if (!row || document.querySelector(".cgm-home")) return;

  const found = Object.fromEntries([...row.children].map((col) => [slotOf(col), col]));
  const games = document.querySelector(".daily-status-updates")?.closest('[class*="col"]');
  if (games) found.games = games;
  if (!found.news) return; // not the layout this was written for; leave the page alone

  const column = (name, order) => {
    const col = Object.assign(document.createElement("div"), { className: `cgm-col cgm-col-${name}` });
    order.forEach((key) => found[key] && col.append(found[key]));
    return col;
  };
  const home = Object.assign(document.createElement("div"), { className: "cgm-home" });
  home.append(column("side", ["articles", "roster", "analysts"]), column("main", ["news"]), column("aside", ["games", "comments"]));
  row.before(home);
  row.remove();

  // Secondary sections start folded; what the user opens stays open next visit.
  const card = (key) => found[key]?.querySelector(".card-based");
  const open = { articles: true, news: true, roster: false, analysts: false, comments: false };
  const shells = Object.fromEntries(Object.entries(open).map(([key, isOpen]) => [key, accordion(card(key), `home-${key}`, { open: isOpen })]));

  if (shells.news) buildNews(shells.news.body);

  if (shells.articles) {
    const items = [...shells.articles.body.querySelectorAll(".news-card")];
    limit(items, 5, shells.articles.body, "articles");
  }

  const table = shells.roster?.body.querySelector("table");
  if (table) limit([...table.tBodies[0].rows], 10, table, "changes");

  if (shells.comments) {
    limit([...shells.comments.body.querySelectorAll(".comment-card")], 4, shells.comments.body, "comments");
  }

  const box = document.querySelector(".daily-status-updates");
  if (box) buildGames(box);
}
return { buildNews, buildGames, buildHome };
})();

