// ---- src/bbm-images.js
const { teamFile, logoPath, normalizeName, espnIdFor, headshotURL, initials, headshot, teamLogo, enhanceTables, enhanceCards, enhanceGames, enhanceAll } = (() => {
// Team logos (bundled) and player headshots (ESPN CDN) for BBM pages.
// Logos resolve from the team abbreviation in each row. Headshots resolve
// from the ESPN id map in bbm-espn.js; unknown players get an initials chip.


// BBM abbreviations that differ from the ESPN file names.
const TEAM_FILE = { GSW: "gs", NOR: "no", SAS: "sa", UTA: "utah", WAS: "wsh", NYK: "ny", PHO: "phx" };

// Display names ESPN spells differently from BBM.
const ALIASES = { "Alexandre Sarr": "Alex Sarr", "Trey Murphy": "Trey Murphy III" };

function teamFile(abbrev) {
  const key = String(abbrev || "").trim().toUpperCase();
  if (!key || key === "FA") return null;
  return (TEAM_FILE[key] || key.toLowerCase()) + ".png";
}

function logoPath(abbrev) {
  const file = teamFile(abbrev);
  return file ? `src/assets/nba/${file}` : null;
}

function normalizeName(name) {
  return String(name || "")
    .replace(/\./g, "")
    .replace(/\s+/g, " ")
    .replace(/\s+(III|IV|II|Jr|Sr|V)$/i, "")
    .trim();
}

const normalizedIds = new Map(Object.entries(ESPN_IDS).map(([name, id]) => [normalizeName(name), id]));

function espnIdFor(name) {
  if (!name) return null;
  const clean = String(name).trim();
  if (ESPN_IDS[clean] != null) return ESPN_IDS[clean];
  const alias = ALIASES[clean];
  if (alias && ESPN_IDS[alias] != null) return ESPN_IDS[alias];
  return normalizedIds.get(normalizeName(clean)) ?? null;
}

function headshotURL(id) {
  return id == null ? null : `https://a.espncdn.com/i/headshots/nba/players/full/${id}.png`;
}

function initials(name) {
  const parts = String(name || "").trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  return (parts[0][0] + (parts.length > 1 ? parts.at(-1)[0] : "")).toUpperCase();
}

const assetURL = (path) => {
  try {
    if (typeof chrome !== "undefined" && chrome.runtime?.getURL) return chrome.runtime.getURL(path);
  } catch { /* the audit harness has no chrome runtime; fall through */ }
  try {
    return new URL(path.replace(/^src\//, ""), import.meta.url).href;
  } catch {
    return path;
  }
};

function chipFor(className, label, fallbackText) {
  const chip = document.createElement("span");
  chip.className = `${className} cgm-fallback`;
  chip.textContent = fallbackText;
  chip.title = label || "";
  chip.setAttribute("aria-hidden", "true");
  return chip;
}

function image(source, className, label, fallbackText) {
  if (source == null || source === "") {
    return fallbackText ? chipFor(className, label, fallbackText) : null;
  }
  const img = document.createElement("img");
  img.className = className;
  img.src = source;
  img.alt = "";
  img.loading = "lazy";
  img.decoding = "async";
  img.setAttribute("aria-hidden", "true");
  if (fallbackText) {
    img.title = label || "";
    img.addEventListener("error", () => {
      img.replaceWith(chipFor(className, label, fallbackText));
    }, { once: true });
  } else {
    img.addEventListener("error", () => img.remove(), { once: true });
  }
  return img;
}

function headshotFor(name) {
  return image(headshotURL(espnIdFor(name)), "cgm-head", name, initials(name));
}

// Big headshot for the playerinfo hero. Same source and initials fallback as
// the inline chips, only the size class differs.
function headshot(name, cls = "cgm-head") {
  return image(headshotURL(espnIdFor(name)), cls, name, initials(name));
}

function teamLogo(abbrev, cls = "cgm-logo") {
  const logo = logoFor(abbrev);
  if (logo) logo.className = cls;
  return logo;
}

function logoFor(abbrev) {
  const path = logoPath(abbrev);
  if (!path) return null;
  return image(assetURL(path), "cgm-logo", String(abbrev).trim().toUpperCase(), null);
}

function tagPlayer(link) {
  if (!link || link.dataset.cgmImg) return;
  link.dataset.cgmImg = "1";
  const name = link.textContent.trim();
  const chip = document.createElement("span");
  chip.className = "cgm-id";
  link.before(chip);
  chip.append(headshotFor(name), link);
}

function tagTeam(cell) {
  if (!cell || cell.dataset.cgmImg) return;
  const logo = logoFor(cell.textContent);
  if (!logo) return;
  cell.dataset.cgmImg = "1";
  cell.prepend(logo);
}

function enhanceTables(root = document) {
  for (const table of root.querySelectorAll("table")) {
    if (!table.querySelector('a[href*="playerinfo.aspx" i], a[href*="playerInfo.aspx"]')) continue;
    for (const row of table.rows) {
      if ([...row.children].every((cell) => cell.tagName === "TH")) continue;
      const link = row.querySelector('a[href*="playerinfo.aspx" i], a[href*="playerInfo.aspx"]');
      if (!link) continue;
      tagPlayer(link);
      // The rankings grid puts the team in the cell after the name.
      const cells = [...row.children];
      const at = cells.findIndex((cell) => cell.contains(link));
      const team = cells.slice(at + 1).find((cell) => cell.classList.contains("tdc"));
      if (team) tagTeam(team);
    }
  }
}

function enhanceCards(root = document) {
  for (const holder of root.querySelectorAll(".display-player")) {
    const link = holder.querySelector(".display-player-name");
    if (link) tagPlayer(link);
    else if (!holder.dataset.cgmImg && holder.querySelector("a")) tagPlayer(holder.querySelector("a"));
    const team = holder.querySelector(".display-player-team");
    if (team && !team.dataset.cgmImg) {
      const logo = logoFor(team.textContent);
      if (logo) { team.dataset.cgmImg = "1"; team.prepend(logo); }
    }
  }
}

function enhanceGames(root = document) {
  for (const box of root.querySelectorAll(".daily-status-updates")) {
    for (const span of box.querySelectorAll(".daily-status-updates-teams span")) {
      if (span.dataset.cgmImg || span.querySelector("img")) continue;
      const logo = logoFor(span.textContent);
      if (logo) { span.dataset.cgmImg = "1"; span.prepend(logo); }
    }
    for (const link of box.querySelectorAll('a[href*="playerinfo.aspx" i], a[href*="playerInfo.aspx"]')) tagPlayer(link);
  }
}

let watching = false;

function enhanceAll(root = document) {
  enhanceTables(root);
  enhanceCards(root);
  enhanceGames(root);
  if (watching || root !== document || !document.body) return;
  watching = true;
  let queued = false;
  new MutationObserver(() => {
    if (queued) return;
    queued = true;
    setTimeout(() => { queued = false; enhanceAll(); }, 300);
  }).observe(document.body, { childList: true, subtree: true });
}
return { teamFile, logoPath, normalizeName, espnIdFor, headshotURL, initials, headshot, teamLogo, enhanceTables, enhanceCards, enhanceGames, enhanceAll };
})();

// ---- src/bbm-news.js
const { buildNewsPage } = (() => {
// Player News (playernews.aspx) has four columns that all open at full length:
// comments, polls, news and the games list. Fold each to a short list with a
// "Show all" toggle, reuse the Home news filters, and keep the rest collapsed.



function buildNewsPage() {
  const comments = document.querySelectorAll("#ContentPlaceHolder1_CommentsPanel .comment-card");
  if (comments.length) limit([...comments], 3, comments[0].parentElement, "comments");

  const holder = document.querySelector(".q-up-holder");
  if (holder) limit([...holder.querySelectorAll(".q-up-item")], 3, holder, "polls");

  const news = document.querySelector("#ContentPlaceHolder1_NewsPanel .card-based");
  const shell = news && accordion(news, "news-page-news", { open: true });
  if (shell) buildNews(shell.body);

  const games = document.querySelector(".daily-status-updates");
  if (games) buildGames(games);

  // The returning-players list runs long beside the news; give it its own scroll.
  const returning = document.getElementById("LongTermInjuriedCB")?.closest(".border");
  if (returning) returning.classList.add("cgm-scroll");
}
return { buildNewsPage };
})();

// ---- src/bbm-legibility.js
const { fixLegibility } = (() => {
// The site colours some text for the opposite theme (white on a pale row, dark
// orange on a dark header). Where text is demonstrably under 4.5:1 against its
// real backdrop, move that one element's colour toward black or white until it
// reads. Nothing else is touched, so correct styling is never overridden.


const SKIP = /^(SCRIPT|STYLE|OPTION|SVG|PATH|I|INPUT|SELECT|TEXTAREA)$/;
const ownText = (el) => [...el.childNodes].some((node) => node.nodeType === 3 && node.textContent.trim());

// Chrome serialises color-mix() as color(srgb r g b), so accept both forms.
function toRgb(value) {
  const srgb = String(value).match(/^color\(srgb ([\d.]+) ([\d.]+) ([\d.]+)(?: \/ ([\d.]+))?\)/);
  if (srgb) return { rgb: [srgb[1], srgb[2], srgb[3]].map((n) => Math.round(+n * 255)), alpha: srgb[4] === undefined ? 1 : +srgb[4] };
  const rgb = parseColor(value);
  const alpha = String(value).match(/rgba\([^)]*,\s*([\d.]+)\)/);
  return rgb ? { rgb, alpha: alpha ? +alpha[1] : 1 } : null;
}

function backdrop(el) {
  const chain = [];
  for (let node = el; node; node = node.parentElement) chain.push(node);
  let color = [255, 255, 255];
  for (const node of chain.reverse()) {
    const layer = toRgb(getComputedStyle(node).backgroundColor);
    if (layer && layer.alpha > 0) color = color.map((c, i) => c * (1 - layer.alpha) + layer.rgb[i] * layer.alpha);
  }
  return color.map(Math.round);
}

function fixLegibility() {
  const visible = (el) => { const rect = el.getBoundingClientRect(); return rect.width > 1 && rect.height > 1; };
  const jobs = [];
  for (const el of document.body.querySelectorAll("*")) {
    if (SKIP.test(el.tagName.toUpperCase()) || !ownText(el) || el.closest("svg, .bm-tooltip-content, [hidden], [data-cgm-chip]")) continue;
    const style = getComputedStyle(el);
    if (style.visibility === "hidden" || style.display === "none" || !visible(el)) continue;
    // Tag chips paint with -webkit-text-fill-color, which wins over color.
    const fill = style.webkitTextFillColor !== style.color;
    const text = toRgb(fill ? style.webkitTextFillColor : style.color);
    if (!text) continue;
    jobs.push({ el, text: text.rgb, alpha: text.alpha, fill });
  }
  // Read everything first, write second, so one fix cannot change another's backdrop mid-pass.
  const fixes = [];
  for (const { el, text, alpha, fill } of jobs) {
    const back = backdrop(el);
    const effective = text.map((c, i) => Math.round(c * alpha + back[i] * (1 - alpha)));
    const fixed = ensureTextContrast(effective, back);
    if (fixed.some((value, index) => value !== effective[index])) fixes.push([el, toCss(fixed), fill]);
  }
  window.__cgmLegibility = `${jobs.length} checked, ${fixes.length} fixed`;
  for (const [el, color, fill] of fixes) el.style.setProperty(fill ? "-webkit-text-fill-color" : "color", color, "important");
}
return { fixLegibility };
})();

// ---- src/bbm-player.js
const { buildPlayer } = (() => {
// Playerinfo hero and tooling. The badge strip becomes one card: a big
// headshot, the name with status and positions, and the facts as a two-sided
// table on the right. The page actions and view toggles move into one toolbox
// section, the schedule strip becomes day cards, and the stat toggles become
// grouped chips. Nodes move, never clones, so postbacks keep working.


const text = (node) => node?.textContent?.trim() ?? "";

// "Amen Thompson - HOU - PG SG": the name is the first text run, the team
// sits between dashes, positions are the colored spans.
function parseHeading(h1) {
  const raw = h1.firstChild?.nodeType === 3 ? h1.firstChild.textContent : h1.textContent;
  const name = raw.split(" - ")[0].trim() || text(h1).split(" - ")[0].trim() || text(h1);
  const team = (raw.match(/-\s*([A-Z]{2,3})\s*-/) || [])[1] || "";
  const positions = [...h1.querySelectorAll("span")].map((span) => text(span)).filter(Boolean);
  return { name, team, positions };
}

const STATUS_TINT = [
  [/probable/i, "#16a34a"],
  [/questionable/i, "#d97706"],
  [/doubtful/i, "#ea580c"],
  [/\bout\b/i, "#dc2626"],
];

function statusPill(value) {
  const pill = document.createElement("span");
  pill.className = "cgm-hero-status";
  pill.textContent = value;
  const tint = STATUS_TINT.find(([pattern]) => pattern.test(value));
  pill.style.backgroundColor = tint ? tint[1] : "#64748b";
  return pill;
}

// Labeled badge items split three ways: the status fact joins the name, the
// positions fact is already shown as pills, and the rest become table pairs.
// Unlabeled items (links, the watch button) are page actions.
function collectBadge(badge) {
  const pairs = [];
  const actions = [];
  let status = null;
  for (const item of [...badge.querySelectorAll(".player-stat-badge-item")]) {
    const label = text(item.querySelector(".player-stat-badge-label"));
    const rest = [...item.childNodes].filter((node) => !node.classList?.contains("player-stat-badge-label"));
    if (!label) {
      actions.push(...rest);
      continue;
    }
    if (/status/i.test(label) && !/questionable|games/i.test(label)) {
      status = rest.map(text).filter(Boolean).join(" ") || text(item);
      continue;
    }
    if (/positions? played/i.test(label)) continue;
    pairs.push({ label, nodes: rest });
  }
  return { pairs, actions, status };
}

function buildSub(team, positions) {
  const sub = document.createElement("div");
  sub.className = "cgm-hero-sub";
  const logo = team ? teamLogo(team, "cgm-hero-logo") : null;
  if (logo) sub.append(logo);
  if (team) sub.append(Object.assign(document.createElement("span"), { className: "cgm-hero-team", textContent: team }));
  for (const position of positions) {
    sub.append(Object.assign(document.createElement("span"), { className: "cgm-hero-pos", textContent: position }));
  }
  return sub.children.length ? sub : null;
}

function buildFacts(pairs) {
  const table = document.createElement("table");
  table.className = "cgm-hero-facts";
  const body = document.createElement("tbody");
  table.append(body);
  for (let at = 0; at < pairs.length; at += 2) {
    const row = document.createElement("tr");
    for (const pair of pairs.slice(at, at + 2)) {
      row.append(Object.assign(document.createElement("th"), { scope: "row", textContent: pair.label }));
      const value = document.createElement("td");
      value.append(...pair.nodes);
      row.append(value);
    }
    body.append(row);
  }
  return body.rows.length ? table : null;
}

function buildHero(h1, badge) {
  const { name, team, positions } = parseHeading(h1);
  const { pairs, actions, status } = collectBadge(badge);
  const hero = document.createElement("section");
  hero.className = "cgm-hero";
  hero.setAttribute("aria-label", `${name} details`);

  const photo = document.createElement("div");
  photo.className = "cgm-hero-photo";
  photo.append(headshot(name, "cgm-hero-head") || document.createTextNode(""));
  hero.append(photo);

  const main = document.createElement("div");
  main.className = "cgm-hero-main";
  hero.append(main);

  h1.classList.add("cgm-hero-name");
  h1.textContent = name;
  const title = document.createElement("div");
  title.className = "cgm-hero-title";
  title.append(h1);
  if (status) title.append(statusPill(status));
  main.append(title);

  const sub = buildSub(team, positions);
  if (sub) main.append(sub);

  const facts = buildFacts(pairs);
  if (facts) hero.append(facts);
  return { hero, actions };
}

// One toolbox card holds the page actions plus the section toggles. The
// sections the reader always wants are expanded; the custom-comment toggle
// and its block go away entirely.
const ALWAYS_OPEN = [/user comments/i, /tracked leagues/i, /recent news/i];

function moveToggles(views) {
  for (const header of [...document.querySelectorAll(".collapse-control-header")]) {
    const toggle = header.querySelector('[data-toggle="collapse"]');
    const label = text(toggle);
    if (/custom comment/i.test(label)) {
      header.closest("div[id]")?.remove();
      const target = toggle?.getAttribute("data-target");
      if (target) document.querySelector(target)?.remove();
      continue;
    }
    if (!toggle) continue;
    views.append(header);
  }
}

function expandPinned() {
  for (const header of [...document.querySelectorAll(".collapse-control-header")]) {
    const toggle = header.querySelector('[data-toggle="collapse"]');
    const target = toggle?.getAttribute("data-target");
    if (!target || !ALWAYS_OPEN.some((pattern) => pattern.test(text(toggle)))) continue;
    document.querySelector(target)?.classList.add("show");
    toggle.setAttribute("aria-expanded", "true");
  }
}

function buildToolbox(actions) {
  const box = document.createElement("section");
  box.className = "cgm-toolbox";
  box.setAttribute("aria-label", "Player tools");
  const doGroup = document.createElement("div");
  doGroup.className = "cgm-tool-group";
  doGroup.append(Object.assign(document.createElement("span"), { className: "cgm-tool-title", textContent: "Actions" }));
  const buttons = document.createElement("div");
  buttons.className = "cgm-tool-buttons";
  const watches = actions.filter((node) => node.name === "ToggleWatchButton");
  const rest = actions.filter((node) => node.name !== "ToggleWatchButton");
  buttons.append(...watches.slice(0, 1), ...rest);
  doGroup.append(buttons);
  const topWatch = [...document.querySelectorAll('.container-fluid input[value*="Watch" i]')].find((input) => input.type === "submit" && !doGroup.contains(input));
  if (topWatch && !buttons.querySelector('[name="ToggleWatchButton"]')) buttons.prepend(topWatch);
  // The page ships the same Watch submit twice. One stays in the toolbox;
  // every other copy goes, wherever it sits.
  const kept = buttons.querySelector('[name="ToggleWatchButton"]');
  if (kept) {
    for (const duplicate of [...document.querySelectorAll('[name="ToggleWatchButton"]')]) {
      if (duplicate !== kept) duplicate.remove();
    }
  }
  if (buttons.children.length) box.append(doGroup);

  const views = document.createElement("div");
  views.className = "cgm-tool-group";
  views.append(Object.assign(document.createElement("span"), { className: "cgm-tool-title", textContent: "Sections" }));
  const chips = document.createElement("div");
  chips.className = "cgm-tool-buttons";
  views.append(chips);
  moveToggles(chips);
  expandPinned();
  if (chips.children.length) box.append(views);
  return box.children.length ? box : null;
}

// The schedule grid becomes a scrolling strip of day cards: date on top, the
// opponent as a home/away pill, off days dimmed. The table stays in the DOM.
function scheduleTable() {
  const days = /^(mon|tue|wed|thu|fri|sat|sun)$/i;
  return [...document.querySelectorAll("table.modern-stats-table")].find((table) => {
    const first = [...(table.querySelector("thead tr") || table.querySelector("tr"))?.children || []].map((cell) => cell.textContent.trim());
    return first.length > 7 && first.every((cell) => days.test(cell));
  });
}

function buildSchedule() {
  const table = scheduleTable();
  if (!table || document.querySelector(".cgm-sched")) return null;
  const rows = [...table.querySelectorAll("tr")].map((row) => [...row.children].map(text));
  if (rows.length < 3) return null;
  const strip = document.createElement("div");
  strip.className = "cgm-sched";
  strip.setAttribute("aria-label", "Schedule");
  rows[0].forEach((day, at) => {
    const card = document.createElement("div");
    card.className = "cgm-day";
    card.append(Object.assign(document.createElement("span"), { className: "cgm-day-dow", textContent: day }));
    card.append(Object.assign(document.createElement("span"), { className: "cgm-day-date", textContent: rows[1][at] || "" }));
    const game = (rows[2][at] || "").trim();
    if (game) {
      const away = game.startsWith("@");
      card.append(Object.assign(document.createElement("span"), {
        className: `cgm-day-game ${away ? "cgm-away" : "cgm-home"}`,
        textContent: away ? game.slice(1) : game,
      }));
      if (away) card.title = `at ${game.slice(1)}`;
    } else {
      card.classList.add("cgm-off");
    }
    strip.append(card);
  });
  table.classList.add("cgm-sched-src");
  table.before(strip);
  return strip;
}

// The stat toggles read as one mess: a submit, bare checkboxes and labels in
// a row. Group them with titles so each control's job is visible. Inputs move
// with their labels, so the postbacks keep working.
function toggleGroup(input) {
  if (input.type === "submit") return "Defaults";
  return /pergame|total|per36/i.test(input.id || input.name || "") ? "Stats" : "Display";
}

function wrapPair(input) {
  const pair = document.createElement("label");
  pair.className = "cgm-toggle";
  const caption = input.type === "submit" ? input : input.nextElementSibling?.tagName === "LABEL" ? input.nextElementSibling : null;
  input.before(pair);
  pair.append(input);
  if (caption && caption !== input) pair.append(caption);
  if (input.type === "checkbox") pair.classList.toggle("cgm-on", input.checked);
  return pair;
}

function buildStatToggles(anchor) {
  const host = anchor?.parentElement;
  if (!host || document.querySelector(".cgm-toggles")) return null;
  const bar = document.createElement("div");
  bar.className = "cgm-toggles";
  const boxes = {};
  for (const title of ["Defaults", "Stats", "Display"]) {
    const wrap = document.createElement("div");
    wrap.className = "cgm-toggle-group";
    wrap.append(Object.assign(document.createElement("span"), { className: "cgm-toggle-title", textContent: title }));
    boxes[title] = wrap;
  }
  for (const input of [...host.querySelectorAll("input")]) {
    boxes[toggleGroup(input)].append(wrapPair(input));
  }
  for (const wrap of Object.values(boxes)) {
    if (wrap.querySelector(".cgm-toggle")) bar.append(wrap);
  }
  if (!bar.children.length) return null;
  host.before(bar);
  if (!text(host)) host.remove();
  return bar;
}

function buildPlayer() {
  if (document.querySelector(".cgm-hero")) return;
  const badge = document.querySelector(".player-stat-badge");
  const h1 = document.querySelector(".page-header h1") || document.querySelector("h1");
  if (!badge || !h1) return;
  const box = badge.closest(".flat-container");

  const { hero, actions } = buildHero(h1, badge);
  const toolbox = buildToolbox(actions);
  box?.before(hero);
  if (toolbox) hero.after(toolbox);
  badge.remove();
  if (box && !text(box)) box.remove();

  buildSchedule();
  const toggles = [...document.querySelectorAll(".ml-2")].find((el) => el.querySelector('input[type="checkbox"]'));
  if (toggles) buildStatToggles(toggles);
}
return { buildPlayer };
})();

// ---- src/bbm-tiers.js
const { buildTiers } = (() => {
// Drafting Tiers renders every tier with its commentary and players, which is
// a very long page. Fold each tier to one row (name plus a player preview) and
// keep BBM's own position tabs, search and jump buttons working.


function buildTiers() {
  const root = document.querySelector(".drafting-tiers");
  if (!root) return;
  const tiers = () => [...root.querySelectorAll(".dt-tier")];
  const toggle = (tier, folded) => tier.classList.toggle("cgm-folded", folded);

  const seen = new Set();
  for (const tier of tiers()) {
    const head = tier.querySelector(".dt-tier-head");
    const names = [...tier.querySelectorAll(".dt-player")].map((player) => player.dataset.dtName).filter(Boolean);
    const preview = Object.assign(document.createElement("span"), { className: "cgm-preview", textContent: names.join(" · ") });
    head?.append(preview);
    head?.addEventListener("click", (event) => { if (!event.target.closest("a")) toggle(tier, !tier.classList.contains("cgm-folded")); });
    // The first tier of each position list starts open; the rest wait.
    const position = tier.dataset.dtPosition || "";
    toggle(tier, seen.has(position));
    seen.add(position);
  }

  clamp(root.querySelector(".dt-summary"));

  const all = Object.assign(document.createElement("button"), { type: "button", className: "cgm-seg-btn cgm-tier-all", textContent: "Expand all" });
  all.addEventListener("click", () => {
    const open = all.textContent === "Expand all";
    tiers().forEach((tier) => toggle(tier, !open));
    all.textContent = open ? "Collapse all" : "Expand all";
  });
  root.querySelector(".dt-toolbar")?.append(all);

  // Jumping to a folded tier must show it.
  root.addEventListener("click", (event) => {
    const jump = event.target.closest(".dt-jump-btn");
    if (!jump) return;
    const tier = root.querySelector(`#DraftingTiers-tier-${jump.dataset.dtJump}`);
    if (!tier) return;
    toggle(tier, false);
    setTimeout(() => tier.scrollIntoView({ block: "start" }), 0);
  });
  // Searching has to see every player.
  root.querySelector(".dt-search")?.addEventListener("input", (event) => {
    if (event.target.value) tiers().forEach((tier) => toggle(tier, false));
  });
}
return { buildTiers };
})();

// ---- src/bbm-page.js
(() => {
// Entry point for the Basketball Monster redesign. The theme and layout work
// is split by component; this decides which pieces a page gets.













const page = (window.__cgmPage || location.pathname.split("/").pop() || "default").replace(/\.aspx$/i, "").toLowerCase() || "default";

// One broken step must not take the rest of the page down with it.
function step(name, work) {
  try { work(); } catch (error) {
    console.error(`ClutchGM redesign step "${name}" failed`, error);
    (window.__cgmErrors ||= []).push(`${name}: ${error.message}`);
  }
}

function run() {
  document.documentElement.classList.add("cgm-bbm");
  document.documentElement.classList.add(`cgm-page-${page}`);
  step("appbar", buildAppBar);
  step("controlbar", buildControlBar);
  if (page === "default" || page === "") step("home", buildHome);
  if (page === "playernews") step("news", buildNewsPage);
  if (page === "depthcharts") step("depth", buildDepth);
  if (page === "positiontiers") step("tiers", buildTiers);
  if (page === "playerinfo") step("player", buildPlayer);
  step("notices", foldNotices);
  step("tones", () => {
    // Comment cards carry their age shade as an inline border colour. Keep the
    // colour as a custom property so the card can tint its fill instead.
    for (const card of document.querySelectorAll(".comment-card[style*='border-color']")) {
      card.style.setProperty("--cgm-tone", card.style.borderColor);
      card.style.borderColor = "";
    }
  });
  step("status", () => {
    // News cards take their tint from the status badge colour.
    for (const badge of document.querySelectorAll(".news-card-test-status-corner")) {
      badge.closest(".news-card")?.style.setProperty("--cgm-status", badge.style.backgroundColor);
    }
  });
  step("boards", buildBoards);
  step("images", () => enhanceAll());

  // Colour fixes depend on which stylesheet is live, so they wait for it, then
  // look once more for late-rendered pieces.
  const paint = () => { step("paint", paintBoards); step("legibility", fixLegibility); };
  if (document.readyState === "complete") paint();
  else addEventListener("load", paint, { once: true });
  setTimeout(paint, 2000);
  step("theme", () => onThemeChange(() => { applyHeat(); fixLegibility(); }));
}

if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", run, { once: true });
else run();
})();
